/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: view, mount
 * Tests
 *   - the box shows the last submitted name and kind, the folder name after a folder-name run, and nothing before a run or after a tag run
 *   - an empty or blank name cannot be submitted, a link is refused until edited, and a name is sent trimmed with its kind
 *   - the box keeps no history, is no search landmark and is disabled with the summary
 *   - an existing-Album review prefills its saved Album title before a run and after a catalog run, while a submitted name or a folder run wins
 *   - the Artist is optional, prefilled from the last submitted run and sent trimmed beside the name, and an empty one is sent as none
 *   - an Artist alone never looks up, and a link in it is refused in place with the name's message
 *   - the hint names what an empty Artist uses
 * @end-catalog */

import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { LookupBox } from './LookupBox';
import type { ImportLookupView } from './importLookupApi';

/**
 * The summary's name box on its own: what it shows for each kind of run, the names and optional Artist names it accepts and
 * refuses, the hint about an empty Artist, and that it keeps no history and is disabled with the summary. All names are synthetic.
 */
const view = (input: ImportLookupView['input']) => ({ input }) as ImportLookupView;
function mount(lookup: { input: { trigger: string; submitted: ImportLookupView['input']['submitted'] } } | null, disabled = false, defaultText?: string,
  mode: 'import' | 'review' = 'import') {
  const onSubmit = vi.fn();
  render(<LookupBox lookup={lookup} rootLabel="Synthetic Folder" defaultText={defaultText} mode={mode} disabled={disabled} onSubmit={onSubmit} />);
  const box = screen.getByRole('group', { name: 'Look up by name' });
  return { onSubmit, box, name: within(box).getByRole('textbox', { name: 'Name' }), artist: within(box).getByRole('textbox', { name: 'Artist (optional)' }),
    submit: within(box).getByRole('button', { name: 'Look up' }) };
}
afterEach(cleanup);

test('the box shows the last submitted name and kind, the folder name after a folder-name run, and nothing before a run or after a tag run', () => {
  let rendered = mount(view({ trigger: 'submitted', submitted: { kind: 'song', text: 'Typed Song' } }));
  expect(rendered.name).toHaveValue('Typed Song'); expect(within(rendered.box).getByRole('radio', { name: 'Song name' })).toBeChecked();
  cleanup();
  rendered = mount(view({ trigger: 'folder', submitted: null }));
  expect(rendered.name).toHaveValue('Synthetic Folder'); expect(within(rendered.box).getByRole('radio', { name: 'Album name' })).toBeChecked();
  for (const lookup of [null, view({ trigger: 'tags', submitted: null })]) {
    cleanup(); rendered = mount(lookup);
    expect(rendered.name).toHaveValue(''); expect(rendered.submit).toBeDisabled();
    expect(within(rendered.box).getByRole('radio', { name: 'Album name' })).toBeChecked();
  }
});

test('an empty or blank name cannot be submitted, a link is refused until edited, and a name is sent trimmed with its kind', () => {
  const { onSubmit, box, name, artist, submit } = mount(null);
  expect(name).toHaveAttribute('maxlength', '200'); expect(name).toHaveAttribute('autocomplete', 'off');
  fireEvent.change(name, { target: { value: '   ' } }); expect(submit).toBeDisabled();
  for (const link of ['www.example.test/album', 'HTTPS://example.test/release/1']) {
    fireEvent.change(name, { target: { value: link } }); fireEvent.click(submit);
    expect(within(box).getByRole('alert')).toHaveTextContent('Enter a name, not a link.');
    expect(name).toHaveAttribute('aria-invalid', 'true'); expect(name).toHaveAccessibleDescription('Enter a name, not a link.');
    // The refusal names the name's field only: the Artist field keeps just its hint.
    expect(artist).toHaveAttribute('aria-invalid', 'false'); expect(artist).toHaveAccessibleDescription("Leave empty to use the files' artist tags.");
  }
  expect(onSubmit).not.toHaveBeenCalled();
  // Editing clears the refusal; a name that only mentions a dot is a name.
  fireEvent.change(name, { target: { value: ' Synthetic Vol. 2 ' } });
  expect(within(box).queryByRole('alert')).not.toBeInTheDocument(); expect(name).toHaveAttribute('aria-invalid', 'false');
  fireEvent.submit(name.closest('form')!);
  expect(onSubmit).toHaveBeenCalledWith('album', 'Synthetic Vol. 2', null);
});

test('the box keeps no history, is no search landmark and is disabled with the summary', () => {
  localStorage.clear(); sessionStorage.clear();
  const { onSubmit, box, name, artist, submit } = mount(null, true);
  expect(box).toBeDisabled(); expect(name).toBeDisabled(); expect(artist).toBeDisabled(); expect(submit).toBeDisabled();
  expect(artist).toHaveAttribute('maxlength', '200'); expect(artist).toHaveAttribute('autocomplete', 'off'); expect(artist).not.toHaveAttribute('list');
  for (const radio of within(box).getAllByRole('radio')) expect(radio).toBeDisabled();
  expect(screen.queryByRole('search')).not.toBeInTheDocument(); expect(screen.queryByRole('searchbox')).not.toBeInTheDocument();
  expect(screen.queryByRole('listbox')).not.toBeInTheDocument(); expect(name).not.toHaveAttribute('list');
  cleanup();
  const enabled = mount(null);
  fireEvent.change(enabled.name, { target: { value: 'Synthetic Album' } }); fireEvent.click(enabled.submit);
  expect(enabled.onSubmit).toHaveBeenCalledOnce(); expect(onSubmit).not.toHaveBeenCalled();
  expect([localStorage.length, sessionStorage.length]).toEqual([0, 0]);
});

test('an existing-Album review prefills its saved Album title before a run and after a catalog run, while a submitted name or a folder run wins', () => {
  let rendered = mount(null, false, 'Synthetic saved Album');
  expect(rendered.name).toHaveValue('Synthetic saved Album'); expect(rendered.submit).toBeEnabled();
  fireEvent.click(rendered.submit); expect(rendered.onSubmit).toHaveBeenCalledWith('album', 'Synthetic saved Album', null);
  cleanup(); rendered = mount({ input: { trigger: 'catalog', submitted: null } }, false, 'Synthetic saved Album');
  expect(rendered.name).toHaveValue('Synthetic saved Album');
  cleanup(); rendered = mount(view({ trigger: 'submitted', submitted: { kind: 'song', text: 'Typed Song' } }), false, 'Synthetic saved Album');
  expect(rendered.name).toHaveValue('Typed Song');
  cleanup(); rendered = mount(view({ trigger: 'folder', submitted: null }), false, 'Synthetic saved Album');
  expect(rendered.name).toHaveValue('Synthetic Folder');
});

test('the Artist is optional, prefilled from the last submitted run and sent trimmed beside the name, and an empty one is sent as none', () => {
  let rendered = mount(view({ trigger: 'submitted', submitted: { kind: 'song', text: 'Typed Song', artist: 'Typed Artist' } }));
  expect(rendered.artist).toHaveValue('Typed Artist');
  fireEvent.click(rendered.submit); expect(rendered.onSubmit).toHaveBeenLastCalledWith('song', 'Typed Song', 'Typed Artist');
  fireEvent.change(rendered.artist, { target: { value: '  Synthetic  Singer ' } }); fireEvent.click(rendered.submit);
  expect(rendered.onSubmit).toHaveBeenLastCalledWith('song', 'Typed Song', 'Synthetic  Singer');
  fireEvent.change(rendered.artist, { target: { value: '   ' } }); fireEvent.click(rendered.submit);
  expect(rendered.onSubmit).toHaveBeenLastCalledWith('song', 'Typed Song', null);
  // A view without the key, a folder run and no run at all start with an empty Artist.
  for (const lookup of [view({ trigger: 'submitted', submitted: { kind: 'album', text: 'Typed Album' } }), view({ trigger: 'folder', submitted: null }), null]) {
    cleanup(); rendered = mount(lookup);
    expect(rendered.artist).toHaveValue('');
  }
});

test('an Artist alone never looks up, and a link in it is refused in place with the name\'s message', () => {
  const { onSubmit, box, name, artist, submit } = mount(null);
  fireEvent.change(artist, { target: { value: 'Synthetic Ensemble' } });
  expect(submit).toBeDisabled();
  fireEvent.submit(name.closest('form')!); expect(onSubmit).not.toHaveBeenCalled();
  fireEvent.change(name, { target: { value: 'Synthetic Album' } });
  fireEvent.change(artist, { target: { value: 'www.example.test' } }); fireEvent.click(submit);
  expect(within(box).getByRole('alert')).toHaveTextContent('Enter a name, not a link.');
  expect(artist).toHaveAttribute('aria-invalid', 'true'); expect(name).toHaveAttribute('aria-invalid', 'false');
  expect(artist).toHaveAccessibleDescription("Enter a name, not a link. Leave empty to use the files' artist tags.");
  expect(onSubmit).not.toHaveBeenCalled();
  // Editing the name leaves the Artist's refusal; editing the Artist clears it.
  fireEvent.change(name, { target: { value: 'Synthetic Album 2' } }); expect(within(box).getByRole('alert')).toBeInTheDocument();
  fireEvent.change(artist, { target: { value: 'Synthetic Ensemble' } });
  expect(within(box).queryByRole('alert')).not.toBeInTheDocument(); expect(artist).toHaveAttribute('aria-invalid', 'false');
  fireEvent.click(submit); expect(onSubmit).toHaveBeenCalledWith('album', 'Synthetic Album 2', 'Synthetic Ensemble');
  // A link in both fields marks both, under one message.
  fireEvent.change(name, { target: { value: 'www.example.test/album' } }); fireEvent.change(artist, { target: { value: 'https://example.test/artist' } });
  fireEvent.click(submit);
  expect(within(box).getAllByRole('alert')).toHaveLength(1);
  expect([name, artist].map(field => field.getAttribute('aria-invalid'))).toEqual(['true', 'true']); expect(onSubmit).toHaveBeenCalledTimes(1);
});

test('the hint names what an empty Artist uses', () => {
  let rendered = mount(null);
  expect(rendered.artist).toHaveAccessibleDescription("Leave empty to use the files' artist tags.");
  cleanup(); rendered = mount(null, false, 'Synthetic saved Album', 'review');
  expect(rendered.artist).toHaveAccessibleDescription("Leave empty to use the Album's primary Artists.");
  expect(rendered.name).not.toHaveAccessibleDescription();
});
